def calcrot(w,q): return R.from_rotvec(np.asarray(w)*q).as_matrix()
def axisfit(qs,ps):
 qs=np.array(qs);ps=np.array(ps)
 coef=np.linalg.lstsq(np.c_[np.ones(len(qs)),np.cos(qs),np.sin(qs)],ps,rcond=None)[0]
