  wn=x[:3]/np.linalg.norm(x[:3]); cn=x[3:]; pred=np.array([cn+calcrot(wn,q)@(ps[0]-cn) for q in qs]);return np.r_[(pred-ps).ravel(), (cn-ps[0])@wn]
 fit=least_squares(fun,np.r_[w,c]); w=fit.x[:3]/np.linalg.norm(fit.x[:3]); c=fit.x[3:]
 return w,c
thumbaxes=[]
for j in thumbinds:
 qs=[0.];ps=[pzero[0]]
 for row in hcdata[1:]:
  if abs(row['q'][j])>.05 and sum(abs(row['q'][jj])>.03 for jj in thumbinds)==1:
   qs.append(row['q'][j]);ps.append(row['tips'][0][0])
 thumbaxes.append(axisfit(qs,ps))

fingeraxes=[]
for fi,inds in enumerate(fingers):
 p0=pzero[fi+1]; axes=[]
 for j in [inds[0],inds[2],inds[3]]:
  qs=[];ps=[]
  for row in hcdata[1:]:
   if abs(row['q'][j])>.05 and sum(abs(row['q'][jj])>.03 for jj in inds)==1:
