    if abs(p[0]-p0[0])<.009: qs.append(row['q'][j]);ps.append(p)
  mat=[];rhs=[]
  for q,p in zip(qs,ps):
   rot=calcrot([1,0,0],q); mat.append((np.eye(3)-rot)[1:,1:]);rhs.append((p-rot@p0)[1:])
  yz=np.linalg.lstsq(np.concatenate(mat),np.concatenate(rhs),rcond=None)[0]; c=np.r_[p0[0],yz]; axes.append((np.array([1.,0,0]),c))
 # AA axis before FE, nearly normal to palm
